'use strict';

// MODULES //

var assign = require( './assign.js' );


// VARIABLES //

var tmp = [ 0.0, 0.0, 0.0, 0.0 ];


// MAIN //

/**
* Compute the Airy function of the second kind, Bi(x).
*
* @param {number} x - input value
* @returns {number} Bi(x)
*
* @example
* var v = bi( 0.3 );
* // returns ~0.752
*
* @example
* v = bi( 0.0 );
* // returns ~0.615
*
* @example
* v = bi( Infinity );
* // returns Infinity
*
* @example
* v = bi( NaN );
* // returns NaN
*
*/
function bi( x ) {
	assign( x, tmp, 1, 0 );
	return tmp[ 2 ];
}


// EXPORTS //

module.exports = bi;
